INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ce7f', 1, 'Heat the oil in a large, heavy-based pan. Add the onions and cook gently for 5 – 10 mins until softened.');
