INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cee5', 'Breakfast Potatoes', 'Danie: Canadian. Źródło: TheMealDB', 'breakfast', 4) ON CONFLICT (id) DO NOTHING;
